package cr.wrbaterias.wr;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.webkit.*;import android.view.Window;import android.graphics.Color;
public class MainActivity extends Activity { WebView web; public void onCreate(Bundle b){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);web=new WebView(this);web.setBackgroundColor(Color.WHITE);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setBuiltInZoomControls(false);s.setDisplayZoomControls(false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return open(r.getUrl());}public boolean shouldOverrideUrlLoading(WebView v,String u){return open(Uri.parse(u));}boolean open(Uri u){String x=u.getScheme();if(x!=null&&(x.equals("http")||x.equals("https")||x.equals("tel")||x.equals("mailto"))){try{startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}catch(Exception e){}}return false;}});web.loadUrl("file:///android_asset/index.html");setContentView(web);}boolean open(Uri u){return false;}@Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}}
